const items = $input.all();
const leads = [];
const requestId = $('Prepare Search Parameters').first().json.requestId;
const params = $('Prepare Search Parameters').first().json;

// Ã¢â€â‚¬Ã¢â€â‚¬ ICP from Prepare Search Parameters Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
const allowedIndustries = (params.industry       || '').toLowerCase().split(',').map(x => x.trim()).filter(Boolean);
const allowedLocations  = (params.location       || '').toLowerCase().split(',').map(x => x.trim()).filter(Boolean);
const allowedCities     = (params.priority_cities || '').toLowerCase().split(',').map(x => x.trim()).filter(Boolean);
const allowedRoles      = (params.job_titles     || '').toLowerCase().split(',').map(x => x.trim()).filter(Boolean);

// Ã¢â€â‚¬Ã¢â€â‚¬ Free / personal email providers (merged: microworlds + pipelinelabs lists) Ã¢â€â‚¬Ã¢â€â‚¬
const freeProviders = [
  'gmail.com','yahoo.com','hotmail.com','outlook.com','icloud.com',
  'live.com','msn.com','yahoo.co.uk','yahoo.co.in','comcast.net','rr.com','cox.net',
  'fuse.net','daktel.com','prodigy.net.mx','euronet.nl','sapo.pt'
];

for (const item of items) {
  const d = item.json;

  // Ã¢â€â‚¬Ã¢â€â‚¬ Email validation Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
  if (!d.email) continue;
  const emailDomain = (d.email.split('@')[1] || '').toLowerCase();
  if (freeProviders.includes(emailDomain)) continue;
  // pipelinelabs actor flags low-confidence pattern-matched emails
  if (d.emailStatus === 'pattern_match') continue;

  // Ã¢â€â‚¬Ã¢â€â‚¬ Name (supports microworlds: first_name/last_name/full_name, and pipelinelabs: firstName/lastName/fullName) Ã¢â€â‚¬Ã¢â€â‚¬
  const fullName = d.full_name || d.fullName ||
    ((d.first_name || d.firstName || '') + ' ' + (d.last_name || d.lastName || '')).trim() || 'N/A';

  // Ã¢â€â‚¬Ã¢â€â‚¬ Job title (both actors use 'title'; microworlds also has 'job_title') Ã¢â€â‚¬Ã¢â€â‚¬
  const jobTitleRaw = d.title || d.job_title || 'N/A';

  // Ã¢â€â‚¬Ã¢â€â‚¬ Website Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
  let website = d.organization_website_url || d.company_website || d.company_domain || d.companyDomain || '';
  if (website && !website.startsWith('http')) website = 'https://' + website;

  // Ã¢â€â‚¬Ã¢â€â‚¬ Location (microworlds: city/state/country, pipelinelabs: personCity/companyCity etc.) Ã¢â€â‚¬Ã¢â€â‚¬
  const city    = d.city    || d.personCity    || d.companyCity    || '';
  const state   = d.state   || d.personState   || d.companyState   || '';
  const country = d.country || d.personCountry || d.companyCountry || '';
  const location = [city, state].filter(Boolean).join(', ') || 'N/A';
  const countryName = country || 'N/A';

  // Ã¢â€â‚¬Ã¢â€â‚¬ Industry (microworlds: string, pipelinelabs: companyIndustry array) Ã¢â€â‚¬Ã¢â€â‚¬
  const industryRaw = d.organization_industry || d.industry || d.companyIndustry || 'N/A';
  const industry = Array.isArray(industryRaw) ? industryRaw.join(', ') : industryRaw;

  // Ã¢â€â‚¬Ã¢â€â‚¬ Company size Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
  const companySize = d.organization_employee_count
    ? String(d.organization_employee_count)
    : (d.company_size || d.companySizeRange || (d.companySize ? d.companySize + ' employees' : 'N/A'));

  // Ã¢â€â‚¬Ã¢â€â‚¬ Technologies (both actors return arrays under different keys) Ã¢â€â‚¬Ã¢â€â‚¬
  const techArr = d.organization_technologies || d.company_technologies || d.technologies;
  const techStr = Array.isArray(techArr)
    ? techArr.slice(0, 6).join(', ')
    : (techArr || '');

  // Ã¢â€â‚¬Ã¢â€â‚¬ Specialties (pipelinelabs only) Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
  const specsArr = d.companySpecialties;
  const specsStr = Array.isArray(specsArr) ? specsArr.slice(0, 4).join(', ') : (specsArr || '');

  // Ã¢â€â‚¬Ã¢â€â‚¬ AI Insight Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
  const desc = (d.organization_short_description || d.company_description || d.companyDescription || '').substring(0, 200);
  const aiInsight = [
    desc    ? 'About: ' + desc    : '',
    techStr ? 'Tech: '  + techStr : '',
    specsStr ? 'Focus: ' + specsStr : ''
  ].filter(Boolean).join(' | ');

  // Ã¢â€â‚¬Ã¢â€â‚¬ Research / enrichment fields Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
  const phone = d.organization_primary_phone || d.mobile_number || '';

  const employees = d.organization_employee_count
    ? String(d.organization_employee_count)
    : (d.company_size || d.companySizeRange || d.companySize || '');

  const annualRevenueRaw = d.organization_annual_revenue || d.company_annual_revenue || d.annualRevenue || '';
  const annualRevenue = annualRevenueRaw
    ? (isNaN(Number(annualRevenueRaw)) ? String(annualRevenueRaw) : '$' + Number(annualRevenueRaw).toLocaleString())
    : '';

  const totalFunding = d.organization_total_funding_printed || '';

  const foundedYear = d.organization_founded_year
    ? String(d.organization_founded_year)
    : (d.company_founded_year ? String(d.company_founded_year) : (d.foundedYear ? String(d.foundedYear) : ''));

  const fundingStage = d.organization_latest_funding_stage || d.fundingStage || '';

  const companyLinkedin = d.organization_linkedin_url || d.company_linkedin || d.companyLinkedinUrl || '';

  // Ã¢â€â‚¬Ã¢â€â‚¬ ICP scoring Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
  const companyIndustry = industry.toLowerCase();
  const companyLocation = (location + ' ' + countryName).toLowerCase();
  const jobTitle        = (jobTitleRaw || '').toLowerCase();

  const industryMatch = allowedIndustries.length === 0 ||
    allowedIndustries.some(i => i && companyIndustry.includes(i));
  const locationMatch =
    (allowedCities.length > 0   && allowedCities.some(c => c && companyLocation.includes(c)))   ||
    (allowedLocations.length > 0 && allowedLocations.some(l => l && companyLocation.includes(l)));
  const roleMatch = allowedRoles.length === 0 ||
    allowedRoles.some(r => r && jobTitle.includes(r));

  let score = 0;
  if (industryMatch) score++;
  if (locationMatch) score++;
  if (roleMatch)     score++;

  let icpMatch = 'No Match';
  if (score === 3)      icpMatch = 'Primary';
  else if (score === 2) icpMatch = 'Secondary';
  else if (score === 1) icpMatch = 'Tertiary';

  if (score === 0) continue;

  // Ã¢â€â‚¬Ã¢â€â‚¬ Output Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
  leads.push({
    // Display (Google Sheets)
    'Lead ID':              d.email,
    'Company Name':         d.organization_name || d.company_name || d.companyName || 'N/A',
    'Industry':             industry,
    'Company Size':         companySize,
    'Location':             location,
    'Country':              countryName,
    'Contact Name':         fullName,
    'Designation':          jobTitleRaw,
    'Website':              website       || 'N/A',
    'Email':                d.email,
    'LinkedIn':             d.linkedin_url || d.linkedin || d.linkedinUrl || 'N/A',
    'Lead Source':          'Apify Leads Finder',
    'ICP Match':            icpMatch,
    'Lead Score':           null,
    'Priority':             'Pending',
    'Qualification Status': 'New',
    'AI Insight':           aiInsight,
    'lead_id':              d.email,
    'request_id':           requestId,

    // snake_case for AI prompt + downstream
    contact_name:           fullName,
    job_title:              jobTitleRaw,
    company_name:           d.organization_name || d.company_name || d.companyName || 'N/A',
    company_size:           companySize,
    industry:               industry,
    location:               location,
    country:                countryName,
    email:                  d.email,
    linkedin:               d.linkedin_url || d.linkedin || d.linkedinUrl || 'N/A',
    email_status:           d.emailStatus || 'verified',

    // Research / enrichment
    phone:                  phone,
    employees:              employees,
    annual_revenue:         annualRevenue,
    total_funding:          totalFunding,
    founded_year:           foundedYear,
    funding_stage:          fundingStage,
    company_linkedin:       companyLinkedin,
    specialties:            specsStr,
    technologies:           techStr,
    seniority:              d.seniority_level || d.seniority || '',
    company_description:    d.organization_short_description || d.company_description || d.companyDescription || ''
  });
}

if (leads.length === 0) {
  return [{ json: { _no_results: true, request_id: requestId } }];
}

return leads.map(lead => ({ json: lead }));

