// Small alias table for common ICP phrasing that doesn't literally appear in the enum.
// This is NOT vertical-specific hardcoding Ã¢â‚¬â€ it's grounded in the real confirmed enum,
// just bridging common synonyms (e.g. "SaaS" isn't a LinkedIn industry, but "Computer
// Software" is). Safe to extend over time as you see more ICP phrasings come through.
const INDUSTRY_ALIASES = {
  'saas': 'Computer Software',
  'software': 'Computer Software',
  'tech': 'Information Technology & Services',
  'technology': 'Information Technology & Services',
  'it': 'Information Technology & Services',
  'fintech': 'Financial Services',
