  'manufacturing': 'Industrial Automation',
  'edtech': 'E-Learning',
  'ai': 'Information Technology & Services',
  'cybersecurity': 'Computer & Network Security',
  'security': 'Computer & Network Security'
};

const normalize = (s) => s.toLowerCase().replace(/[&,/]/g, ' ').replace(/\s+/g, ' ').trim();
const ENUM_NORMALIZED = PIPELINELABS_INDUSTRY_ENUM.map(e => ({ original: e, norm: normalize(e) }));

function matchIndustry(term) {
  const t = normalize(term);

  // 1. Alias table (highest confidence)
  if (INDUSTRY_ALIASES[t]) return INDUSTRY_ALIASES[t];

  // 2. Exact normalized match against enum
  const exact = ENUM_NORMALIZED.find(e => e.norm === t);
  if (exact) return exact.original;

  // 3. Substring match either direction
  const substr = ENUM_NORMALIZED.find(e => e.norm.includes(t) || t.includes(e.norm));
  if (substr) return substr.original;

  // 4. Token overlap Ã¢â‚¬â€ match if any significant word (4+ chars) is shared
  const tTokens = t.split(' ').filter(w => w.length >= 4);
  let best = null, bestScore = 0;
  for (const e of ENUM_NORMALIZED) {
    const eTokens = e.norm.split(' ').filter(w => w.length >= 4);
    const overlap = tTokens.filter(w => eTokens.includes(w)).length;
    if (overlap > bestScore) { bestScore = overlap; best = e.original; }
  }
  if (best) return best;

  // 5. No confident match Ã¢â‚¬â€ return null rather than guessing
  return null;
}

const rawIndustryTerms = (p.target_industries || '').split(',').map(s => s.trim()).filter(Boolean);
const matchedIndustries = [];
